'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path'),crypto=require('node:crypto');
const {validateBundle,writeNewBundle,registerBundleIpc}=require('../src/main/feature-bundle');
const file=(name,data=Buffer.from([0,128,255,13,10]))=>({path:name,base64:data.toString('base64'),sha256:crypto.createHash('sha256').update(data).digest('hex')});
const payload=(...files)=>({copyOnly:true,files});
function fixture(t){let dir=fs.mkdtempSync(path.join(os.tmpdir(),'feature-bundle-'));dir=fs.realpathSync(dir);t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));return dir;}
test('bundle writes byte-identical binary, nested text and empty files to a new directory with independently verified hashes',t=>{const dir=fixture(t),target=path.join(dir,'copy'),binary=file('photo.bin'),text=file('资料/notes.txt',Buffer.from('你好\r\n')),empty=file('empty.txt',Buffer.alloc(0));const r=writeNewBundle(target,payload(binary,text,empty));assert.equal(r.ok,true);assert.equal(r.count,3);assert.deepEqual(fs.readFileSync(path.join(target,'photo.bin')),Buffer.from([0,128,255,13,10]));assert.equal(fs.readFileSync(path.join(target,'资料/notes.txt'),'utf8'),'你好\r\n');assert.equal(fs.statSync(path.join(target,'empty.txt')).size,0);for(const row of r.manifest)assert.equal(row.sha256,crypto.createHash('sha256').update(fs.readFileSync(path.join(target,row.path))).digest('hex'));});
test('bundle rejects existing directory and file while preserving their markers',t=>{const dir=fixture(t),target=path.join(dir,'existing');fs.mkdirSync(target);fs.writeFileSync(path.join(target,'marker'),'keep');assert.equal(writeNewBundle(target,payload(file('x'))).ok,false);assert.equal(fs.readFileSync(path.join(target,'marker'),'utf8'),'keep');const old=path.join(dir,'old');fs.writeFileSync(old,'keep-file');assert.equal(writeNewBundle(old,payload(file('x'))).ok,false);assert.equal(fs.readFileSync(old,'utf8'),'keep-file');});
test('bundle validates all hashes and canonical base64 before making any directory',t=>{const dir=fixture(t);for(const bad of [{...file('b'),sha256:'0'.repeat(64)},{...file('b'),base64:'AB=='},{...file('b'),base64:'!!!!'},{...file('b'),base64:'AA'}]){const target=path.join(dir,'bad');assert.equal(writeNewBundle(target,payload(file('good'),bad)).ok,false);assert.equal(fs.existsSync(target),false);}});
test('bundle rejects absolute/traversal/reserved paths and case/unicode collisions without touching outside files',t=>{const dir=fixture(t),marker=path.join(dir,'marker');fs.writeFileSync(marker,'outside');for(const p of ['../marker','/tmp/x','C:/x','a/../x','a//b','a\\b','CON.txt','folder/NUL','foo.','foo ','a:stream'])assert.throws(()=>validateBundle(payload(file(p))));for(const paths of [['a','A'],['a','a/x'],['é','e\u0301']])assert.throws(()=>validateBundle(payload(...paths.map(p=>file(p)))));assert.equal(fs.readFileSync(marker,'utf8'),'outside');});
test('bundle enforces count, per-file and total size limits and explicit copyOnly',()=>{assert.throws(()=>validateBundle({files:[file('x')]}));assert.throws(()=>validateBundle(payload()));assert.throws(()=>validateBundle(payload(...Array.from({length:101},(_,i)=>file('f'+i)))));assert.throws(()=>validateBundle(payload(file('large',Buffer.alloc(2*1024*1024+1)))));assert.throws(()=>validateBundle(payload(...Array.from({length:6},(_,i)=>file('f'+i,Buffer.alloc(2*1024*1024))))));});
test('bundle accepts maximum-size canonical payload and rejects total bound with its specific error',()=>{const large=Buffer.alloc(2*1024*1024,255);assert.equal(validateBundle(payload(file('maximum.bin',large))).total,large.length);assert.throws(()=>validateBundle(payload(...Array.from({length:6},(_,i)=>file('f'+i,large)))),/10MiB/);assert.throws(()=>validateBundle(payload(file('\ud800.txt'))),/相对路径/);});
test('bundle removes its own new directory on a mid-write failure and leaves preexisting siblings intact',t=>{const dir=fixture(t),target=path.join(dir,'copy'),marker=path.join(dir,'marker');fs.writeFileSync(marker,'keep');let calls=0;const r=writeNewBundle(target,payload(file('a'),file('nested/b')),{writeFile:(name,data,options)=>{if(++calls===2)throw Error('simulated storage failure');fs.writeFileSync(name,data,options);}});assert.equal(r.ok,false);assert.equal(fs.existsSync(target),false);assert.equal(fs.readFileSync(marker,'utf8'),'keep');});
test('bundle IPC validates before native dialog, respects cancel and uses dialog-selected destination rather than renderer paths',async t=>{const dir=fixture(t);let handler,dialogs=0,cancel=true;registerBundleIpc({handle:(name,fn)=>{assert.equal(name,'files:exportBundle');handler=fn;}},{dialog:{showSaveDialog:async()=>{dialogs++;return cancel?{canceled:true}:{canceled:false,filePath:path.join(dir,'chosen')};}},getWindow:()=>null,getDownloads:()=>dir});assert.equal((await handler({},payload({...file('a'),sha256:'bad'}))).ok,false);assert.equal(dialogs,0);assert.deepEqual(await handler({},payload(file('a'))),{ok:false,canceled:true});cancel=false;const r=await handler({}, {...payload(file('a')),target:path.join(dir,'renderer-target')});assert.equal(r.ok,true);assert.equal(r.path,path.join(dir,'chosen'));assert.equal(fs.existsSync(path.join(dir,'renderer-target')),false);});
